(()=>{
'use strict';
const D=window.PARTENER_DATA;
if(!D||!Array.isArray(D.calls))return;

const DB_NAME='partener-consultant-v3';
const DB_VERSION=1;
const STATE_KEY='workspace';
const LOCAL_KEY='partener_consultant_v3_state';
const V2_KEY='partener_consultant_v2_state';
const REGIONS=['Nord-Est','Sud-Est','Sud-Muntenia','Sud-Vest Oltenia','Vest','Nord-Vest','Centru','București-Ilfov'];
const COUNTIES=['Alba','Arad','Argeș','Bacău','Bihor','Bistrița-Năsăud','Botoșani','Brașov','Brăila','București','Buzău','Călărași','Caraș-Severin','Cluj','Constanța','Covasna','Dâmbovița','Dolj','Galați','Giurgiu','Gorj','Harghita','Hunedoara','Ialomița','Iași','Ilfov','Maramureș','Mehedinți','Mureș','Neamț','Olt','Prahova','Sălaj','Satu Mare','Sibiu','Suceava','Teleorman','Timiș','Tulcea','Vaslui','Vâlcea','Vrancea'];
const TYPE_LABELS={
 food_industry_enterprise:'Întreprindere din industria alimentară',agricultural_enterprise:'Întreprindere agricolă',microenterprise:'Microîntreprindere',small_enterprise:'Întreprindere mică',medium_enterprise:'Întreprindere mijlocie',enterprise:'Întreprindere',employer:'Angajator',social_enterprise:'Întreprindere socială',industrial_park:'Parc industrial / operator',ngo:'ONG / asociație / fundație',training_provider:'Furnizor de formare profesională',accredited_private_social_service_provider:'Furnizor privat de servicii sociale',public_school:'Unitate de învățământ publică',private_school:'Unitate de învățământ privată',public_university:'Universitate publică',private_university:'Universitate privată',university:'Universitate',employment_provider:'Furnizor servicii de ocupare',public_authority:'Autoritate / instituție publică',municipality:'UAT',county_council:'Consiliu județean',ministry:'Minister / autoritate centrală',cluster:'Cluster',research_organisation:'Organizație de cercetare',health_provider:'Furnizor servicii de sănătate'
};
const OBJECTIVE_LABELS={renewable_energy:'Energie regenerabilă',energy_autoconsumption:'Autoconsum energetic',digitalization:'Digitalizare',social_services:'Servicii sociale',critical_technologies:'Tehnologii critice',adult_training:'Formarea adulților',vocational_training:'Formare profesională',innovation:'Inovare',education:'Educație',employment:'Ocupare',youth_employment:'Ocuparea tinerilor',neet:'Tineri NEET',transnational_mobility:'Mobilitate transnațională',social_inclusion:'Incluziune socială',tourism:'Turism',urban_regeneration:'Regenerare urbană',green_infrastructure:'Infrastructură verde',mobility:'Mobilitate',industrial_parks:'Parcuri industriale',productive_investment:'Investiții productive',energy_efficiency:'Eficiență energetică',rural_development:'Dezvoltare rurală',education_infrastructure:'Infrastructură educațională',health:'Sănătate',research:'Cercetare',circular_economy:'Economie circulară'};
const PROGRAMMES=['PEO','PoIDS','PDDS','PTJ','AFIR','Programe Regionale','PNRR','Programul Sănătate','STEP','Altele'];
const DOC_CATEGORIES=['Document juridic','Certificat constatator / CAEN','Situații financiare','Document fiscal','Proprietate / drept de folosință','Autorizație / aviz','Studiu / documentație tehnică','CV / resurse umane','Parteneriat','Ofertă / fundamentare cost','Cerere / anexă','Alt document'];
const QUESTIONNAIRE=[
 ['applicant','Clasa solicitantului este eligibilă în forma finală a ghidului?'],
 ['territory','Locul de implementare și teritoriul sunt eligibile?'],
 ['activity','Activitatea / CAEN-ul / investiția propusă sunt eligibile?'],
 ['financial','Clientul îndeplinește condițiile financiare și de capacitate?'],
 ['cofinance','Cofinanțarea și cash-flow-ul sunt asigurate?'],
 ['property','Dreptul asupra imobilului / activelor este suficient?'],
 ['stateAid','Încadrarea în ajutor de stat / minimis este verificată?'],
 ['documents','Documentele obligatorii pot fi obținute până la depunere?']
];

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]||c));
const norm=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const uid=p=>`${p}-${(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2))}`;
const humanize=k=>OBJECTIVE_LABELS[k]||TYPE_LABELS[k]||String(k||'').replaceAll('_',' ').replace(/\b\w/g,m=>m.toUpperCase());
const fmtBytes=n=>{const x=Number(n||0);if(x<1024)return `${x} B`;if(x<1024*1024)return `${(x/1024).toFixed(1)} KB`;return `${(x/1024/1024).toFixed(1)} MB`};
const todayISO=()=>new Date().toISOString().slice(0,10);

let dbPromise=null;
let storageMode='indexeddb';
function openDB(){
 if(dbPromise)return dbPromise;
 dbPromise=new Promise((resolve,reject)=>{
  if(!window.indexedDB){reject(new Error('IndexedDB unavailable'));return}
  const req=indexedDB.open(DB_NAME,DB_VERSION);
  req.onupgradeneeded=()=>{
   const db=req.result;
   if(!db.objectStoreNames.contains('kv'))db.createObjectStore('kv',{keyPath:'key'});
   if(!db.objectStoreNames.contains('documents')){
    const s=db.createObjectStore('documents',{keyPath:'id'});
    s.createIndex('clientId','clientId',{unique:false});
    s.createIndex('callId','callId',{unique:false});
   }
  };
  req.onsuccess=()=>resolve(req.result);
  req.onerror=()=>reject(req.error||new Error('IndexedDB error'));
 });
 return dbPromise;
}
async function idbGetState(){const db=await openDB();return new Promise((resolve,reject)=>{const r=db.transaction('kv','readonly').objectStore('kv').get(STATE_KEY);r.onsuccess=()=>resolve(r.result?.value||null);r.onerror=()=>reject(r.error)})}
async function idbPutState(value){const db=await openDB();return new Promise((resolve,reject)=>{const r=db.transaction('kv','readwrite').objectStore('kv').put({key:STATE_KEY,value});r.onsuccess=()=>resolve();r.onerror=()=>reject(r.error)})}
async function idbPutDocument(doc){const db=await openDB();return new Promise((resolve,reject)=>{const r=db.transaction('documents','readwrite').objectStore('documents').put(doc);r.onsuccess=()=>resolve();r.onerror=()=>reject(r.error)})}
async function idbGetDocument(id){const db=await openDB();return new Promise((resolve,reject)=>{const r=db.transaction('documents','readonly').objectStore('documents').get(id);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error)})}
async function idbDeleteDocument(id){const db=await openDB();return new Promise((resolve,reject)=>{const r=db.transaction('documents','readwrite').objectStore('documents').delete(id);r.onsuccess=()=>resolve();r.onerror=()=>reject(r.error)})}
async function idbListDocuments(clientId){const db=await openDB();return new Promise((resolve,reject)=>{const store=db.transaction('documents','readonly').objectStore('documents');const req=clientId?store.index('clientId').getAll(clientId):store.getAll();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>reject(req.error)})}
async function idbClearDocuments(){const db=await openDB();return new Promise((resolve,reject)=>{const r=db.transaction('documents','readwrite').objectStore('documents').clear();r.onsuccess=()=>resolve();r.onerror=()=>reject(r.error)})}

function safeLocalGet(key){try{return JSON.parse(localStorage.getItem(key)||'null')}catch{return null}}
function safeLocalSet(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{}}
function baseState(){return {version:3,clients:[],selectedClientId:null,tab:'dashboard',selectedCallId:null,tracked:{},compare:{},tasks:[],evaluations:{},filters:{q:'',status:'ALL',minScore:0,onlyTracked:false},editingClient:null,demoClientsRemoved:false,deletedClientIds:[],updatedAt:new Date().toISOString()}}
function normaliseClient(c={}){return {id:c.id||uid('client'),name:c.name||'',cui:c.cui||'',type:c.type||'',county:c.county||'',region:c.region||'',caen:c.caen||'',employees:c.employees||'',turnover:c.turnover||'',ageYears:c.ageYears||'',projectValue:c.projectValue||'',objectives:Array.isArray(c.objectives)?c.objectives:[],preferredProgrammes:Array.isArray(c.preferredProgrammes)?c.preferredProgrammes:[],projectIdea:c.projectIdea||'',contact:c.contact||'',email:c.email||'',phone:c.phone||'',notes:c.notes||'',seed:!!c.seed,createdAt:c.createdAt||new Date().toISOString(),updatedAt:c.updatedAt||new Date().toISOString()}}
function migrateV2(v2){const s=baseState();if(!v2)return s;s.clients=(v2.clients||[]).map(normaliseClient);s.selectedClientId=v2.selected||s.clients[0]?.id||null;s.tracked=v2.tracked||{};s.tasks=(v2.tasks||[]).map(t=>({...t,id:t.id||uid('task'),createdAt:t.createdAt||new Date().toISOString()}));s.tab='dashboard';return s}
function mergeSeeds(s){s.clients=Array.isArray(s.clients)?s.clients.map(normaliseClient):[];s.deletedClientIds=Array.isArray(s.deletedClientIds)?s.deletedClientIds:[];const deleted=new Set(s.deletedClientIds);if(!s.demoClientsRemoved){for(const raw of (D.clients||[])){if(!deleted.has(raw.id)&&!s.clients.some(c=>c.id===raw.id))s.clients.push(normaliseClient({...raw,seed:true}))}}if(s.selectedClientId&&!s.clients.some(c=>c.id===s.selectedClientId))s.selectedClientId=null;if(!s.selectedClientId&&s.clients[0])s.selectedClientId=s.clients[0].id;s.tracked=s.tracked||{};s.compare=s.compare||{};s.tasks=Array.isArray(s.tasks)?s.tasks:[];s.evaluations=s.evaluations||{};s.filters={q:'',status:'ALL',minScore:0,onlyTracked:false,...(s.filters||{})};s.version=3;return s}

let state=baseState();
let documents=[];
let saveTimer=null;
let ready=false;
let lastSaveState='salvat';

async function loadState(){
 let loaded=null;
 try{loaded=await idbGetState()}catch(e){storageMode='localStorage';loaded=safeLocalGet(LOCAL_KEY)}
 if(!loaded){loaded=safeLocalGet(LOCAL_KEY)}
 if(!loaded){loaded=migrateV2(safeLocalGet(V2_KEY))}
 state=mergeSeeds(loaded||baseState());
 await persistNow();
 ready=true;
}
async function persistNow(){
 state.updatedAt=new Date().toISOString();
 safeLocalSet(LOCAL_KEY,state);
 try{await idbPutState(state);storageMode='indexeddb'}catch{storageMode='localStorage'}
 lastSaveState='salvat';
 const el=document.querySelector('[data-cw3-save-state]');if(el)el.textContent='Salvat';
}
function persist(){lastSaveState='se salvează';const el=document.querySelector('[data-cw3-save-state]');if(el)el.textContent='Se salvează…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>persistNow(),180)}

function selectedClient(){return state.clients.find(c=>c.id===state.selectedClientId)||state.clients[0]||null}
function trackedSet(client){return new Set(state.tracked[client?.id]||[])}
function compareSet(client){return new Set(state.compare[client?.id]||[])}
function clientTasks(client){return state.tasks.filter(t=>t.clientId===client.id).sort((a,b)=>(Number(a.done)-Number(b.done))||({CRITICAL:0,HIGH:1,MEDIUM:2,LOW:3}[a.priority]??4)-({CRITICAL:0,HIGH:1,MEDIUM:2,LOW:3}[b.priority]??4)||String(a.due||'9999').localeCompare(String(b.due||'9999')))}
function allTypes(){return [...new Set(D.calls.flatMap(c=>c.applicantKeys||[]).concat(Object.keys(TYPE_LABELS)).concat(state.clients.map(c=>c.type).filter(Boolean)))].sort((a,b)=>humanize(a).localeCompare(humanize(b),'ro'))}
function allObjectives(){return [...new Set(D.calls.flatMap(c=>c.objectiveKeys||[]).concat(Object.keys(OBJECTIVE_LABELS)).concat(state.clients.flatMap(c=>c.objectives||[])))].sort((a,b)=>humanize(a).localeCompare(humanize(b),'ro'))}
function clientCompleteness(c){const checks=[c.name,c.cui,c.type,c.county,c.region,c.caen||c.type==='ngo'||c.type==='public_authority'||c.type==='municipality',(c.objectives||[]).length,c.projectIdea,c.contact||c.email||c.phone,c.projectValue];return Math.round(checks.filter(Boolean).length/checks.length*100)}
function profileGaps(c){const gaps=[];if(!c.cui)gaps.push('CUI / identificare');if(!c.type)gaps.push('tip organizație');if(!c.county)gaps.push('județ');if(!c.region)gaps.push('regiune');if(!c.caen&&!['ngo','public_authority','municipality','county_council','ministry','public_school','private_school','public_university','private_university'].includes(c.type))gaps.push('CAEN');if(!(c.objectives||[]).length)gaps.push('obiective');if(!c.projectIdea)gaps.push('idee de proiect');if(!c.projectValue)gaps.push('valoare proiect');if(!c.contact&&!c.email&&!c.phone)gaps.push('contact');return gaps}

function applicantGate(call,client){const keys=call.applicantKeys||[];if(!client.type)return {state:'UNKNOWN',label:'Tipul clientului lipsește',detail:'Completează tipul organizației.'};if(!keys.length)return {state:'UNKNOWN',label:'Lista solicitanților nu este structurată',detail:'Verifică lista din ghidul final.'};if(keys.includes(client.type))return {state:'PASS',label:'Clasă de solicitant găsită',detail:humanize(client.type)};return {state:'FAIL',label:'Clasa nu apare în lista structurată',detail:'Poate exista rol de partener sau o excepție; verificarea ghidului rămâne obligatorie.'}}
function territoryGate(call,client){const text=norm(`${call.region||''} ${call.summary||''}`);const region=norm(client.region);if(!client.region)return {state:'UNKNOWN',label:'Regiunea clientului lipsește',detail:'Completează regiunea.'};if(/\bromania\b|\bnational\b|toate regiunile|nivel national/.test(text)){if(/regiuni(ile)? mai putin dezvoltate|fara bucuresti|exceptand bucuresti|bucuresti.?ilfov exclus/.test(text)&&region.includes('bucuresti'))return {state:'FAIL',label:'București-Ilfov exclus',detail:call.region||''};return {state:'PASS',label:'Aplicabilitate națională',detail:call.region||'România'}}if(region&&text.includes(region))return {state:'PASS',label:'Regiunea este explicită',detail:client.region};const named=REGIONS.some(r=>text.includes(norm(r)));if(named)return {state:'FAIL',label:'Alt teritoriu explicit',detail:call.region||''};return {state:'UNKNOWN',label:'Teritoriu neconfirmat',detail:'Verifică aria eligibilă din ghid.'}}
function statusGate(call){if(call.status==='CLOSED'||call.status==='CANCELLED')return {state:'FAIL',label:'Apel inactiv',detail:call.status};if(call.status==='OPEN'){const deadline=parseDeadline(call.close);if(deadline&&deadline<Date.now())return {state:'FAIL',label:'Termen expirat / status de reconciliat',detail:`Termen în corpus: ${call.close}. Verifică o eventuală prelungire înainte de acțiune.`};return {state:'PASS',label:'Apel deschis',detail:call.close||'Termen neextras'}}if(['EXPECTED','PUBLIC_CONSULTATION','ANNOUNCED'].includes(call.status))return {state:'UNKNOWN',label:'Pregătire / monitorizare',detail:call.status};return {state:'UNKNOWN',label:'Status de verificat',detail:call.status||'Necunoscut'}}
function dataGate(value,unknownTokens=['vezi ghid','neconfirmat','necunoscut','—']){const text=norm(value);return value&& !unknownTokens.some(x=>text.includes(norm(x)))?{state:'PASS'}:{state:'UNKNOWN'}}
function fit(call,client){
 const applicant=applicantGate(call,client),territory=territoryGate(call,client),status=statusGate(call);
 const overlaps=(client.objectives||[]).filter(o=>(call.objectiveKeys||[]).includes(o));
 const components={applicant:applicant.state==='PASS'?40:applicant.state==='UNKNOWN'?10:0,territory:territory.state==='PASS'?20:territory.state==='UNKNOWN'?7:0,objectives:Math.min(20,overlaps.length?10+overlaps.length*5:0),status:status.state==='PASS'?10:status.state==='UNKNOWN'?4:0,profile:Math.round(clientCompleteness(client)*.1)};
 const score=Object.values(components).reduce((a,b)=>a+b,0);
 const hardFails=[applicant,territory,status].filter(g=>g.state==='FAIL');
 const unknowns=[applicant,territory,status].filter(g=>g.state==='UNKNOWN').map(g=>g.label);
 if(dataGate(call.cofinancing).state!=='PASS')unknowns.push('Cofinanțare neextrasă');
 let label='VERIFICĂ',tone='warn',next='Completează necunoscutele și verifică ghidul final.';
 if(status.state==='FAIL'){label='INACTIV';tone='muted';next='Păstrează doar ca referință sau monitorizează relansarea.'}
 else if(hardFails.length){label='NEPOTRIVIRE CUNOSCUTĂ';tone='bad';next='Verifică dacă există rol eligibil de partener sau o excepție în ghid.'}
 else if(applicant.state==='PASS'&&territory.state==='PASS'&&status.state==='PASS'){label='CANDIDAT DIRECT';tone='good';next='Deschide dosarul și finalizează GO/NO-GO pe condițiile hard.'}
 else if(status.state!=='PASS'&&applicant.state==='PASS'){label='PREGĂTIRE';tone='info';next='Pregătește clientul și urmărește lansarea sau ghidul final.'}
 else if(overlaps.length&&status.state==='PASS'){label='VERIFICĂ ELIGIBILITATEA';tone='warn';next='Potrivirea tematică există; clasa solicitantului trebuie confirmată.'}
 return {score,components,applicant,territory,status,overlaps,hardFails,unknowns,label,tone,next};
}
function ranked(client){return D.calls.filter(c=>!c.newsOnly).map(call=>({call,fit:fit(call,client)})).sort((a,b)=>b.fit.score-a.fit.score||({OPEN:0,PUBLIC_CONSULTATION:1,EXPECTED:2,CLOSED:9}[a.call.status]??5)-({OPEN:0,PUBLIC_CONSULTATION:1,EXPECTED:2,CLOSED:9}[b.call.status]??5))}

const MONTHS={ianuarie:0,februarie:1,martie:2,aprilie:3,mai:4,iunie:5,iulie:6,august:7,septembrie:8,octombrie:9,noiembrie:10,decembrie:11,ian:0,feb:1,mar:2,apr:3,iun:5,iul:6,aug:7,sept:8,oct:9,nov:10,dec:11};
function parseDeadline(value){if(!value)return null;const s=norm(value);let m=s.match(/(\d{1,2})[.\/-](\d{1,2})[.\/-](20\d{2})/);if(m)return new Date(+m[3],+m[2]-1,+m[1],23,59,59);m=s.match(/(\d{1,2})\s+([a-z]+)\s+(20\d{2})/);if(m&&MONTHS[m[2]]!==undefined)return new Date(+m[3],MONTHS[m[2]],+m[1],23,59,59);m=s.match(/(20\d{2})-(\d{1,2})-(\d{1,2})/);if(m)return new Date(+m[1],+m[2]-1,+m[3],23,59,59);return null}
function urgency(call){if(call.status!=='OPEN')return null;const d=parseDeadline(call.close);if(!d)return null;return Math.ceil((d-Date.now())/86400000)}
function urgencyLabel(call){const days=urgency(call);if(days===null)return {text:'Termen de verificat',tone:'muted'};if(days<0)return {text:'Termen depășit',tone:'bad'};if(days<=7)return {text:`${days} zile`,tone:'bad'};if(days<=21)return {text:`${days} zile`,tone:'warn'};return {text:`${days} zile`,tone:'good'}}

function priorityLabel(v){return {CRITICAL:'CRITICĂ',HIGH:'RIDICATĂ',MEDIUM:'MEDIE',LOW:'SCĂZUTĂ'}[String(v||'').toUpperCase()]||String(v||'')}
function statusBadge(s){const labels={OPEN:'DESCHIS',EXPECTED:'ÎN PREGĂTIRE',PUBLIC_CONSULTATION:'ÎN CONSULTARE',ANNOUNCED:'ANUNȚAT',CLOSED:'ÎNCHIS',CANCELLED:'ANULAT',SUSPENDED:'SUSPENDAT',NEWS:'INFORMARE'};return `<span class="cw3Status ${esc(s||'UNKNOWN')}">${esc(labels[String(s||'').toUpperCase()]||'DE VERIFICAT')}</span>`}
function fitBadge(f){return `<span class="cw3Fit ${f.tone}">${esc(f.label)} · ${f.score}/100</span>`}
function gateRow(g){return `<div class="cw3Gate ${g.state}"><span>${g.state==='PASS'?'✓':g.state==='FAIL'?'×':'?'}</span><div><b>${esc(g.label)}</b><small>${esc(g.detail||'')}</small></div></div>`}
function sourceLink(s){return `<a class="cw3Source" href="${esc(s.url)}" target="_blank" rel="noreferrer"><b>${esc(s.label||'Sursă oficială')}</b><span>${esc(s.tier||'T1')} · deschide ↗</span></a>`}

function nav(client){return `<header class="cw3Top"><div><div class="cw3Brand">PARTENER<span>.EU</span></div><small>Spațiu de lucru consultant</small></div><div class="cw3TopActions"><span class="cw3Save" data-cw3-save-state>${esc(lastSaveState==='se salvează'?'Se salvează…':'Salvat')}</span><button class="cw3Btn ghost" data-cw3-export-quick>Backup</button><button class="cw3Btn ghost" data-cw3-exit>Ieși în site</button></div></header>`}
function sidebar(client){return `<aside class="cw3Sidebar"><div class="cw3SideHead"><div><b>Portofoliu</b><span>${state.clients.length} firme / organizații</span></div><button class="cw3Icon" data-cw3-new-client title="Adaugă firmă sau organizație">＋</button></div><button class="cw3AddClient" data-cw3-new-client>＋ Adaugă firmă / organizație</button><div class="cw3ClientManageHint">Selectează o firmă și intră în Profil pentru editare sau ștergere.</div><div class="cw3ClientList">${state.clients.map(c=>`<button class="cw3Client ${c.id===client?.id?'active':''}" data-cw3-client="${esc(c.id)}"><b>${esc(c.name||'Client fără nume')}</b><span>${esc(c.region||'Regiune nesetată')} · ${clientCompleteness(c)}%</span>${c.seed?'<em>EXEMPLU</em>':''}</button>`).join('')}</div>${state.clients.some(c=>c.seed)?'<button class="cw3RemoveDemo" data-cw3-remove-demo>Elimină clienții exemplu</button>':''}<div class="cw3Privacy"><b>Stocare locală</b><span>Profilurile, taskurile și fișierele sunt păstrate în acest browser. Fă backup periodic.</span><small>${storageMode==='indexeddb'?'IndexedDB activ':'Fallback localStorage; fișierele nu pot fi păstrate.'}</small></div></aside>`}
function tabs(){const items=[['dashboard','Panou'],['profile','Profil'],['opportunities','Oportunități'],['dossier','Dosar apel'],['compare','Compară'],['documents','Documente'],['tasks','Taskuri'],['backup','Backup']];return `<nav class="cw3Tabs">${items.map(([id,label])=>`<button class="${state.tab===id?'active':''}" data-cw3-tab="${id}">${label}</button>`).join('')}</nav>`}

function dashboard(client){const rows=ranked(client),tracked=trackedSet(client),tasks=clientTasks(client),urgent=rows.filter(x=>{const d=urgency(x.call);return d!==null&&d>=0&&d<=21}).slice(0,5),top=rows.filter(x=>x.fit.score>=45).slice(0,5),gaps=profileGaps(client);return `<section class="cw3Hero"><div><div class="eyebrow">Panou client</div><h1>${esc(client.name||'Client')}</h1><p>${esc([client.type&&humanize(client.type),client.county,client.region].filter(Boolean).join(' · '))}</p></div><button class="cw3Btn" data-cw3-edit-client>Completează profilul</button><div class="cw3Metrics"><div><b>${clientCompleteness(client)}%</b><span>profil complet</span></div><div><b>${rows.filter(x=>x.call.status==='OPEN'&&x.fit.score>=60).length}</b><span>apeluri deschise cu potrivire bună</span></div><div><b>${tracked.size}</b><span>apeluri urmărite</span></div><div><b>${tasks.filter(t=>!t.done).length}</b><span>taskuri deschise</span></div></div></section><div class="cw3DashboardGrid"><section><div class="cw3SectionHead"><div><h2>Ce merită atenție</h2><p>Potrivire explicabilă cu profilul clientului; nu reprezintă probabilitate de aprobare.</p></div><button class="cw3Btn secondary small" data-cw3-tabgo="opportunities">Vezi toate</button></div><div class="cw3OppList">${top.map(x=>opportunityCard(client,x.call,x.fit,true)).join('')||'<div class="cw3Empty">Completează profilul pentru rezultate mai bune.</div>'}</div></section><aside class="cw3Aside"><div class="cw3Panel"><h3>Date lipsă</h3>${gaps.length?`<ul>${gaps.map(g=>`<li>${esc(g)}</li>`).join('')}</ul>`:'<p>Profilul minim este complet.</p>'}<button class="cw3Btn ghost small" data-cw3-edit-client>Completează</button></div><div class="cw3Panel"><h3>Termene apropiate</h3>${urgent.length?urgent.map(({call})=>{const u=urgencyLabel(call);return `<button class="cw3Deadline" data-cw3-open-call="${esc(call.id)}"><span class="${u.tone}">${esc(u.text)}</span><b>${esc(call.title)}</b><small>${esc(call.close||'')}</small></button>`}).join(''):'<p>Nu există termene parse-uite în următoarele 21 de zile.</p>'}</div><div class="cw3Panel"><h3>Următoarele taskuri</h3>${tasks.filter(t=>!t.done).slice(0,5).map(t=>`<div class="cw3MiniTask"><span class="cw3Priority ${esc(t.priority)}">${esc(priorityLabel(t.priority))}</span><b>${esc(t.title)}</b><small>${esc(t.due||'fără termen')}</small></div>`).join('')||'<p>Nu există taskuri deschise.</p>'}</div></aside></div>`}

function opportunityCard(client,call,f,compact=false){const tracked=trackedSet(client).has(call.id),compared=compareSet(client).has(call.id),u=urgencyLabel(call);return `<article class="cw3Opp ${compact?'compact':''}"><div class="cw3OppTop"><div>${statusBadge(call.status)} ${fitBadge(f)}</div><div class="cw3OppButtons"><button class="cw3Track ${tracked?'on':''}" data-cw3-track="${esc(call.id)}">${tracked?'✓ Urmărit':'＋ Urmărește'}</button><button class="cw3CompareToggle ${compared?'on':''}" data-cw3-compare-toggle="${esc(call.id)}">${compared?'✓ Compară':'⇄ Compară'}</button></div></div><h3>${esc(call.title)}</h3><div class="meta">${esc(call.programme||'')} · ${esc(call.region||'')}</div><p>${esc(call.summary||'')}</p><div class="cw3OppFacts"><span><small>Grant / buget</small><b>${esc(call.grant&&norm(call.grant)!=='vezi ghid'?call.grant:(call.budget||'Vezi ghidul'))}</b></span><span><small>Termen</small><b>${esc(call.status==='OPEN'?(call.close||'De verificat'):(call.consultation||call.close||'Monitorizare'))}</b><em class="${u.tone}">${esc(u.text)}</em></span></div><div class="cw3ScoreParts"><span>Solicitant ${f.components.applicant}/40</span><span>Teritoriu ${f.components.territory}/20</span><span>Obiective ${f.components.objectives}/20</span><span>Status ${f.components.status}/10</span></div><div class="cw3Why"><b>Următorul pas:</b> ${esc(f.next)}</div><div class="cw3RowActions"><button class="cw3Btn small" data-cw3-open-call="${esc(call.id)}">Deschide dosarul</button>${(call.sourceFacts||[])[0]?`<a href="${esc(call.sourceFacts[0].url)}" target="_blank" rel="noreferrer">Sursa oficială ↗</a>`:''}</div></article>`}
function opportunities(client){const filters=state.filters,tracked=trackedSet(client);let rows=ranked(client);if(filters.q)rows=rows.filter(x=>norm(JSON.stringify(x.call)).includes(norm(filters.q)));if(filters.status!=='ALL')rows=rows.filter(x=>x.call.status===filters.status);rows=rows.filter(x=>x.fit.score>=Number(filters.minScore||0));if(filters.onlyTracked)rows=rows.filter(x=>tracked.has(x.call.id));return `<section><div class="cw3SectionHead"><div><h2>Radar de oportunități</h2><p>${rows.length} rezultate. Scorul explică relevanța operațională.</p></div></div><div class="cw3Filters"><input class="cw3Input" id="cw3FilterQ" value="${esc(filters.q)}" placeholder="Caută program, sector, activitate"><select class="cw3Select" id="cw3FilterStatus">${['ALL','OPEN','PUBLIC_CONSULTATION','EXPECTED','CLOSED'].map(s=>`<option ${filters.status===s?'selected':''}>${s}</option>`).join('')}</select><select class="cw3Select" id="cw3FilterScore">${[0,40,55,70,85].map(v=>`<option value="${v}" ${Number(filters.minScore)===v?'selected':''}>Scor minim ${v}</option>`).join('')}</select><label class="cw3Toggle"><input type="checkbox" id="cw3OnlyTracked" ${filters.onlyTracked?'checked':''}><span>Doar urmărite</span></label></div><div class="cw3OppList">${rows.slice(0,80).map(x=>opportunityCard(client,x.call,x.fit)).join('')||'<div class="cw3Empty">Niciun rezultat pentru filtrele selectate.</div>'}</div></section>`}

function evaluationKey(client,call){return `${client.id}:${call.id}`}
function getEvaluation(client,call){const key=evaluationKey(client,call);return state.evaluations[key]||{answers:{},notes:'',decisionNote:'',updatedAt:null}}
function evaluationDecision(client,call){const f=fit(call,client),e=getEvaluation(client,call);const answers=QUESTIONNAIRE.map(([id])=>e.answers[id]||'UNKNOWN');if(f.hardFails.length||answers.includes('NO'))return {label:'NO-GO / BLOCAT',tone:'bad',detail:'Există un hard-gate negativ automat sau confirmat manual.'};if(f.applicant.state==='PASS'&&f.territory.state==='PASS'&&f.status.state==='PASS'&&answers.every(a=>a==='YES'))return {label:'GO PENTRU PREGĂTIRE',tone:'good',detail:'Toate verificările critice sunt confirmate. Nu reprezintă aprobare de finanțare.'};return {label:'DE VERIFICAT',tone:'warn',detail:'Există condiții necunoscute sau neverificate.'}}
function dossier(client){const rows=ranked(client);let call=D.calls.find(c=>c.id===state.selectedCallId)||D.calls.find(c=>trackedSet(client).has(c.id))||rows[0]?.call;if(!call)return '<div class="cw3Empty">Nu există apeluri în corpus.</div>';state.selectedCallId=call.id;const f=fit(call,client),e=getEvaluation(client,call),decision=evaluationDecision(client,call);return `<section><div class="cw3DossierSelect"><label>Dosar activ<select class="cw3Select" id="cw3DossierCall">${rows.slice(0,80).map(x=>`<option value="${esc(x.call.id)}" ${x.call.id===call.id?'selected':''}>${esc(x.call.title)}</option>`).join('')}</select></label></div><div class="cw3DossierHero"><div>${statusBadge(call.status)} ${fitBadge(f)}</div><h1>${esc(call.title)}</h1><p>${esc(call.programme||'')} · ${esc(call.region||'')}</p><div class="cw3Decision ${decision.tone}"><b>${esc(decision.label)}</b><span>${esc(decision.detail)}</span></div><div class="cw3KeyFacts"><div><small>Termen</small><b>${esc(call.status==='OPEN'?(call.close||'Neextras'):(call.consultation||call.close||'Neconfirmat'))}</b></div><div><small>Grant</small><b>${esc(call.grant||'Neextras')}</b></div><div><small>Buget</small><b>${esc(call.budget||'Neextras')}</b></div><div><small>Cofinanțare</small><b>${esc(call.cofinancing||'Neextras')}</b></div></div></div><div class="cw3DossierGrid"><main><div class="cw3Panel"><h2>Condiții eliminatorii automate</h2>${gateRow(f.applicant)}${gateRow(f.territory)}${gateRow(f.status)}${f.unknowns.length?`<div class="cw3Unknown"><b>Necunoscute:</b> ${esc(f.unknowns.join(', '))}</div>`:''}</div><div class="cw3Panel"><h2>Verificare consultant</h2><p>Răspunsurile se referă la clientul selectat și la versiunea curentă a apelului.</p><div class="cw3Questionnaire">${QUESTIONNAIRE.map(([id,label])=>`<label><span>${esc(label)}</span><select class="cw3Select" data-cw3-answer="${id}"><option value="UNKNOWN" ${(e.answers[id]||'UNKNOWN')==='UNKNOWN'?'selected':''}>Necunoscut / de verificat</option><option value="YES" ${e.answers[id]==='YES'?'selected':''}>Da, confirmat</option><option value="NO" ${e.answers[id]==='NO'?'selected':''}>Nu / condiție neîndeplinită</option></select></label>`).join('')}</div><label class="cw3Field">Notă de decizie<textarea class="cw3Input" id="cw3DecisionNote" rows="4" placeholder="Concluzie, condiții, responsabil…">${esc(e.decisionNote||'')}</textarea></label></div><div class="cw3Panel"><h2>Condiții și activități</h2><h3>Eligibilitate cunoscută</h3><ul>${(call.eligibility||[]).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Nu este extrasă complet.</li>'}</ul><h3>Activități</h3><ul>${(call.activities||[]).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Nu sunt extrase complet.</li>'}</ul><h3>Documente</h3><ul>${(call.documents||[]).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Checklistul documentelor nu este extras complet.</li>'}</ul></div></main><aside><div class="cw3Panel"><h3>Acțiuni</h3><button class="cw3Btn wide" data-cw3-generate-tasks="${esc(call.id)}">Generează planul de lucru</button><button class="cw3Btn ghost wide" data-cw3-track="${esc(call.id)}">${trackedSet(client).has(call.id)?'✓ Urmărit':'＋ Urmărește apelul'}</button><button class="cw3Btn ghost wide" data-cw3-docs-for-call="${esc(call.id)}">Documente pentru acest apel</button></div><div class="cw3Panel"><h3>Riscuri</h3>${(call.risks||[]).map(x=>`<div class="cw3Risk">${esc(x)}</div>`).join('')||'<p>Nu sunt extrase riscuri specifice.</p>'}</div><div class="cw3Panel"><h3>Surse</h3>${(call.sourceFacts||[]).map(sourceLink).join('')||'<p>Nu există încă surse legate.</p>'}</div></aside></div></section>`}

function compareView(client){const set=compareSet(client);const candidates=ranked(client).filter(x=>trackedSet(client).has(x.call.id)||set.has(x.call.id)).slice(0,20);const selected=[...set].map(id=>D.calls.find(c=>c.id===id)).filter(Boolean).slice(0,3);return `<section><div class="cw3SectionHead"><div><h2>Compară oportunități</h2><p>Selectează maximum 3 apeluri. Compararea folosește aceleași hard-gates explicabile.</p></div></div><div class="cw3ComparePicker">${candidates.map(({call,fit:f})=>`<label><input type="checkbox" data-cw3-compare-check="${esc(call.id)}" ${set.has(call.id)?'checked':''} ${!set.has(call.id)&&set.size>=3?'disabled':''}><span>${statusBadge(call.status)} <b>${esc(call.title)}</b><small>${f.score}/100</small></span></label>`).join('')||'<div class="cw3Empty">Urmărește câteva apeluri sau adaugă-le la comparație din radar.</div>'}</div>${selected.length?`<div class="cw3CompareTable"><div class="head"><span>Criteriu</span>${selected.map(c=>`<b>${esc(c.title)}</b>`).join('')}</div>${compareRow('Status',selected.map(c=>statusBadge(c.status)),true)}${compareRow('Fit',selected.map(c=>fitBadge(fit(c,client))),true)}${compareRow('Grant',selected.map(c=>esc(c.grant||'Neextras')))}${compareRow('Deadline',selected.map(c=>esc(c.status==='OPEN'?(c.close||'Neextras'):(c.consultation||c.close||'Monitorizare'))))}${compareRow('Solicitant',selected.map(c=>esc(applicantGate(c,client).label)))}${compareRow('Teritoriu',selected.map(c=>esc(territoryGate(c,client).label)))}${compareRow('Cofinanțare',selected.map(c=>esc(c.cofinancing||'Neextras')))}${compareRow('Riscuri',selected.map(c=>String((c.risks||[]).length)))}<div class="cw3CompareActions"><span></span>${selected.map(c=>`<button class="cw3Btn small" data-cw3-open-call="${esc(c.id)}">Dosar</button>`).join('')}</div></div>`:'<div class="cw3Empty">Selectează apelurile pentru comparație.</div>'}</section>`}
function compareRow(label,values,raw=false){return `<div class="row"><b>${esc(label)}</b>${values.map(v=>`<span>${raw?v:esc(v)}</span>`).join('')}</div>`}

async function refreshDocuments(client){try{const all=await idbListDocuments(client?.id);documents=all.map(({blob,...meta})=>meta)}catch{documents=[]}}
function documentsView(client){const callFilter=state.selectedCallId||'';const list=documents.filter(d=>d.clientId===client.id&&(!callFilter||state.tab!=='documents'||true));return `<section><div class="cw3SectionHead"><div><h2>Documente client</h2><p>Fișierele sunt păstrate local în IndexedDB și nu părăsesc browserul.</p></div></div>${storageMode!=='indexeddb'?'<div class="cw3Warning">IndexedDB nu este disponibil. Metadatele pot fi salvate, dar atașamentele nu pot fi păstrate.</div>':''}<form class="cw3Upload" id="cw3UploadForm"><input class="cw3Input" id="cw3Files" type="file" multiple ${storageMode!=='indexeddb'?'disabled':''}><select class="cw3Select" id="cw3DocCategory">${DOC_CATEGORIES.map(x=>`<option>${esc(x)}</option>`).join('')}</select><select class="cw3Select" id="cw3DocCall"><option value="">Document general client</option>${trackedSet(client).size?[...trackedSet(client)].map(id=>D.calls.find(c=>c.id===id)).filter(Boolean).map(c=>`<option value="${esc(c.id)}" ${state.selectedCallId===c.id?'selected':''}>${esc(c.title)}</option>`).join(''):''}</select><button class="cw3Btn" type="submit">Atașează</button></form><div class="cw3DocList">${list.map(d=>`<article class="cw3Document"><div><b>${esc(d.name)}</b><span>${esc(d.category)} · ${fmtBytes(d.size)} · ${esc(new Date(d.addedAt).toLocaleDateString('ro-RO'))}</span>${d.callId?`<small>${esc(D.calls.find(c=>c.id===d.callId)?.title||'Apel')}</small>`:''}</div><div><button class="cw3Btn ghost small" data-cw3-doc-download="${esc(d.id)}">Descarcă</button><button class="cw3Delete" data-cw3-doc-delete="${esc(d.id)}">Șterge</button></div></article>`).join('')||'<div class="cw3Empty">Nu ai atașat documente pentru acest client.</div>'}</div></section>`}

function tasksView(client){const list=clientTasks(client);return `<section><div class="cw3SectionHead"><div><h2>Plan de lucru</h2><p>Sarcini manuale și liste de verificare generate din dosarele apelurilor.</p></div></div><form class="cw3TaskAdd" id="cw3TaskForm"><input class="cw3Input" id="cw3TaskTitle" placeholder="Sarcină nouă" required><input class="cw3Input" id="cw3TaskDue" type="date"><select class="cw3Select" id="cw3TaskPriority"><option>MEDIUM</option><option>HIGH</option><option>CRITICAL</option><option>LOW</option></select><select class="cw3Select" id="cw3TaskCall"><option value="">Fără apel</option>${[...trackedSet(client)].map(id=>D.calls.find(c=>c.id===id)).filter(Boolean).map(c=>`<option value="${esc(c.id)}">${esc(c.title)}</option>`).join('')}</select><button class="cw3Btn" type="submit">Adaugă</button></form><div class="cw3TaskList">${list.map(t=>`<article class="cw3Task ${t.done?'done':''}"><label><input type="checkbox" data-cw3-task-done="${esc(t.id)}" ${t.done?'checked':''}><span></span></label><div><b>${esc(t.title)}</b><small>${esc(t.callId?(D.calls.find(c=>c.id===t.callId)?.title||'Apel'):'Sarcină generală')}${t.due?' · '+esc(t.due):''}</small></div><span class="cw3Priority ${esc(t.priority)}">${esc(priorityLabel(t.priority))}</span><button class="cw3Delete" data-cw3-task-delete="${esc(t.id)}">×</button></article>`).join('')||'<div class="cw3Empty">Nu există sarcini. Generează planul de lucru dintr-un dosar de apel.</div>'}</div></section>`}

function profileForm(client,isNew=false){const c=isNew?normaliseClient({}):client;return `<section><div class="cw3SectionHead"><div><h2>${isNew?'Firmă / organizație nouă':'Profil firmă / organizație'}</h2><p>Datele sunt folosite pentru screening explicabil și pentru dosarul de lucru.</p></div>${!isNew?'<button class="cw3DeleteText" data-cw3-delete-client>Șterge din portofoliu</button>':''}</div><form id="cw3ClientForm" class="cw3Form" data-new="${isNew?'1':'0'}"><label>Nume organizație<input class="cw3Input" id="cw3Name" value="${esc(c.name)}" required></label><label>CUI / identificare<input class="cw3Input" id="cw3Cui" value="${esc(c.cui)}"></label><label>Tip organizație<select class="cw3Select" id="cw3Type"><option value="">Selectează</option>${allTypes().map(t=>`<option value="${esc(t)}" ${c.type===t?'selected':''}>${esc(humanize(t))}</option>`).join('')}</select></label><label>Județ<select class="cw3Select" id="cw3County"><option value="">Selectează</option>${COUNTIES.map(x=>`<option ${c.county===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Regiune<select class="cw3Select" id="cw3Region"><option value="">Selectează</option>${REGIONS.map(x=>`<option ${c.region===x?'selected':''}>${x}</option>`).join('')}</select></label><label>CAEN / activitate principală<input class="cw3Input" id="cw3Caen" value="${esc(c.caen)}" placeholder="ex. 8559 / formare profesională"></label><label>Număr angajați<input class="cw3Input" id="cw3Employees" value="${esc(c.employees)}" inputmode="numeric"></label><label>Cifră de afaceri<input class="cw3Input" id="cw3Turnover" value="${esc(c.turnover)}" placeholder="EUR sau lei"></label><label>Vechime organizație<input class="cw3Input" id="cw3Age" value="${esc(c.ageYears)}" placeholder="ani"></label><label>Valoarea proiectului propus<input class="cw3Input" id="cw3ProjectValue" value="${esc(c.projectValue)}"></label><label>Persoană contact<input class="cw3Input" id="cw3Contact" value="${esc(c.contact)}"></label><label>Email<input class="cw3Input" id="cw3Email" type="email" value="${esc(c.email)}"></label><label>Telefon<input class="cw3Input" id="cw3Phone" value="${esc(c.phone)}"></label><label class="wide">Ideea / nevoia de finanțare<textarea class="cw3Input" id="cw3Idea" rows="4">${esc(c.projectIdea)}</textarea></label><fieldset class="wide"><legend>Obiective urmărite</legend><div class="cw3Checks">${allObjectives().map(o=>`<label><input type="checkbox" data-cw3-objective value="${esc(o)}" ${(c.objectives||[]).includes(o)?'checked':''}><span>${esc(humanize(o))}</span></label>`).join('')}</div></fieldset><fieldset class="wide"><legend>Programe preferate</legend><div class="cw3Checks">${PROGRAMMES.map(p=>`<label><input type="checkbox" data-cw3-programme value="${esc(p)}" ${(c.preferredProgrammes||[]).includes(p)?'checked':''}><span>${esc(p)}</span></label>`).join('')}</div></fieldset><label class="wide">Note interne<textarea class="cw3Input" id="cw3Notes" rows="4">${esc(c.notes)}</textarea></label><div class="wide cw3FormActions"><button class="cw3Btn" type="submit">Salvează profilul</button>${isNew?'<button class="cw3Btn ghost" type="button" data-cw3-cancel-new>Anulează</button>':''}</div></form></section>`}

function backupView(client){return `<section><div class="cw3SectionHead"><div><h2>Backup și portabilitate</h2><p>Exportă portofoliul pentru a evita dependența de un singur browser.</p></div></div><div class="cw3BackupGrid"><div class="cw3Panel"><h3>Export workspace</h3><p>Include clienți, apeluri urmărite, evaluări, comparații și taskuri. Fișierele atașate sunt exportate separat.</p><button class="cw3Btn wide" data-cw3-export>Descarcă backup JSON</button><button class="cw3Btn ghost wide" data-cw3-export-client>Exportă raportul clientului</button></div><div class="cw3Panel"><h3>Import workspace</h3><p>Importul înlocuiește datele de lucru curente după confirmare.</p><input class="cw3Input" type="file" id="cw3ImportFile" accept="application/json"><button class="cw3Btn wide" data-cw3-import>Importă backup</button></div><div class="cw3Panel"><h3>Resetare controlată</h3><p>Șterge workspace-ul local și documentele IndexedDB. Corpusul public nu este afectat.</p><button class="cw3Btn danger wide" data-cw3-reset>Resetează workspace</button></div><div class="cw3Panel"><h3>Stare stocare</h3><div class="cw3KV"><span>Motor</span><b>${esc(storageMode)}</b><span>Ultima salvare</span><b>${esc(new Date(state.updatedAt).toLocaleString('ro-RO'))}</b><span>Documente client</span><b>${documents.filter(d=>d.clientId===client.id).length}</b></div></div></div></section>`}

function renderBody(client){if(state.editingClient==='new')return profileForm(client,true);switch(state.tab){case'profile':return profileForm(client,false);case'opportunities':return opportunities(client);case'dossier':return dossier(client);case'compare':return compareView(client);case'documents':return documentsView(client);case'tasks':return tasksView(client);case'backup':return backupView(client);default:return dashboard(client)}}
async function renderWorkspace(){if(!ready)return;const main=document.querySelector('.main'),mode=document.getElementById('mode');if(!main||!mode||mode.textContent.trim()!=='Public site')return;main.dataset.cw2='1';main.dataset.cw3='1';let client=selectedClient();if(!client&&state.editingClient!=='new'){state.editingClient='new'}if(client)await refreshDocuments(client);main.innerHTML=`<div class="cw3Root">${nav(client)}<div class="cw3Layout">${sidebar(client)}<main class="cw3Main">${client||state.editingClient==='new'?`${client?tabs():''}${renderBody(client||normaliseClient({}))}`:'<div class="cw3Empty"><h2>Adaugă primul client</h2><button class="cw3Btn" data-cw3-new-client>Client nou</button></div>'}</main></div></div>`;bind(main)}

function readClientForm(base){return normaliseClient({...base,name:document.getElementById('cw3Name').value.trim(),cui:document.getElementById('cw3Cui').value.trim(),type:document.getElementById('cw3Type').value,county:document.getElementById('cw3County').value,region:document.getElementById('cw3Region').value,caen:document.getElementById('cw3Caen').value.trim(),employees:document.getElementById('cw3Employees').value.trim(),turnover:document.getElementById('cw3Turnover').value.trim(),ageYears:document.getElementById('cw3Age').value.trim(),projectValue:document.getElementById('cw3ProjectValue').value.trim(),contact:document.getElementById('cw3Contact').value.trim(),email:document.getElementById('cw3Email').value.trim(),phone:document.getElementById('cw3Phone').value.trim(),projectIdea:document.getElementById('cw3Idea').value.trim(),notes:document.getElementById('cw3Notes').value.trim(),objectives:[...document.querySelectorAll('[data-cw3-objective]:checked')].map(x=>x.value),preferredProgrammes:[...document.querySelectorAll('[data-cw3-programme]:checked')].map(x=>x.value),seed:false,updatedAt:new Date().toISOString()})}
function toggleTracked(client,id){const set=trackedSet(client);set.has(id)?set.delete(id):set.add(id);state.tracked[client.id]=[...set];persist();renderWorkspace()}
function toggleCompare(client,id){const set=compareSet(client);if(set.has(id))set.delete(id);else if(set.size<3)set.add(id);else{alert('Poți compara maximum 3 apeluri.');return}state.compare[client.id]=[...set];persist();renderWorkspace()}
function addTask(task){if(state.tasks.some(t=>t.clientId===task.clientId&&t.callId===task.callId&&t.title===task.title&&!t.done))return;state.tasks.push({id:uid('task'),done:false,priority:'MEDIUM',due:'',createdAt:new Date().toISOString(),...task})}
function generateTasks(client,call){const dueDate=parseDeadline(call.close)?.toISOString().slice(0,10)||'';(call.documents||[]).forEach(x=>addTask({clientId:client.id,callId:call.id,title:`Document: ${x}`,priority:call.status==='OPEN'?'HIGH':'MEDIUM'}));(call.risks||[]).slice(0,8).forEach(x=>addTask({clientId:client.id,callId:call.id,title:`Verificare risc: ${x}`,priority:'HIGH'}));QUESTIONNAIRE.forEach(([id,label])=>{const e=getEvaluation(client,call);if((e.answers[id]||'UNKNOWN')==='UNKNOWN')addTask({clientId:client.id,callId:call.id,title:`Eligibilitate: ${label}`,priority:'HIGH'})});if(call.status==='OPEN'&&call.close)addTask({clientId:client.id,callId:call.id,title:`Deadline depunere: ${call.title}`,priority:'CRITICAL',due:dueDate});state.tracked[client.id]=[...new Set([...(state.tracked[client.id]||[]),call.id])];state.tab='tasks';persist();renderWorkspace()}

function downloadBlob(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportState(clientOnly=false){const client=selectedClient();let payload={schema:'PARTENER.EU_CONSULTANT_WORKSPACE_V3',exportedAt:new Date().toISOString(),state};if(clientOnly&&client){payload={schema:'PARTENER.EU_CLIENT_DOSSIER_V3',exportedAt:new Date().toISOString(),client,tracked:state.tracked[client.id]||[],tasks:clientTasks(client),evaluations:Object.fromEntries(Object.entries(state.evaluations).filter(([k])=>k.startsWith(client.id+':'))),documentMetadata:documents.filter(d=>d.clientId===client.id),opportunities:ranked(client).slice(0,20).map(({call,fit:f})=>({id:call.id,title:call.title,status:call.status,programme:call.programme,region:call.region,grant:call.grant,deadline:call.close,fit:{score:f.score,label:f.label,reasons:[f.applicant.label,f.territory.label,f.status.label]}}))}}downloadBlob(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),clientOnly?`partener-client-${norm(client?.name||'client').replace(/\s+/g,'-')}.json`:`partener-workspace-${todayISO()}.json`)}

function bind(root){
 root.querySelectorAll('[data-cw3-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.cw3Tab;state.editingClient=null;persist();renderWorkspace()});
 root.querySelectorAll('[data-cw3-tabgo]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.cw3Tabgo;persist();renderWorkspace()});
 root.querySelectorAll('[data-cw3-client]').forEach(b=>b.onclick=()=>{state.selectedClientId=b.dataset.cw3Client;state.tab='dashboard';state.editingClient=null;state.selectedCallId=null;persist();renderWorkspace()});
 root.querySelectorAll('[data-cw3-new-client]').forEach(b=>b.onclick=async()=>{state.editingClient='new';state.tab='profile';state.selectedCallId=null;await persistNow();await renderWorkspace();setTimeout(()=>document.getElementById('cw3Name')?.focus(),0)});
 root.querySelectorAll('[data-cw3-edit-client]').forEach(b=>b.onclick=()=>{state.tab='profile';state.editingClient=null;persist();renderWorkspace()});
 root.querySelectorAll('[data-cw3-track]').forEach(b=>b.onclick=()=>toggleTracked(selectedClient(),b.dataset.cw3Track));
 root.querySelectorAll('[data-cw3-compare-toggle]').forEach(b=>b.onclick=()=>toggleCompare(selectedClient(),b.dataset.cw3CompareToggle));
 root.querySelectorAll('[data-cw3-open-call]').forEach(b=>b.onclick=()=>{state.selectedCallId=b.dataset.cw3OpenCall;state.tab='dossier';persist();renderWorkspace()});
 root.querySelectorAll('[data-cw3-compare-check]').forEach(b=>b.onchange=()=>toggleCompare(selectedClient(),b.dataset.cw3CompareCheck));
 const form=document.getElementById('cw3ClientForm');if(form)form.onsubmit=async e=>{e.preventDefault();try{const isNew=form.dataset.new==='1';const base=isNew?{}:selectedClient();const client=readClientForm(base);if(!client.name.trim()){alert('Completează numele firmei sau organizației.');return}if(isNew){const duplicate=client.cui&&state.clients.find(c=>c.cui&&norm(c.cui)===norm(client.cui));if(duplicate&&!confirm(`Există deja ${duplicate.name} cu acest CUI. Adaugi totuși o înregistrare separată?`))return;state.clients.push(client);state.selectedClientId=client.id}else{const i=state.clients.findIndex(c=>c.id===client.id);if(i<0){alert('Profilul nu mai există în portofoliu. Reîncarcă pagina.');return}state.clients[i]=client;state.selectedClientId=client.id}state.deletedClientIds=(state.deletedClientIds||[]).filter(id=>id!==client.id);state.editingClient=null;state.tab='dashboard';await persistNow();await renderWorkspace()}catch(err){console.error('Consultant client save failed',err);alert('Nu am putut salva profilul. Datele introduse rămân pe ecran; încearcă din nou.')}};
 root.querySelectorAll('[data-cw3-cancel-new]').forEach(b=>b.onclick=()=>{state.editingClient=null;state.tab='dashboard';renderWorkspace()});
 root.querySelectorAll('[data-cw3-delete-client]').forEach(b=>b.onclick=async()=>{const client=selectedClient();if(!client||!confirm(`Ștergi din portofoliu ${client.name}? Profilul, sarcinile și evaluările locale vor fi eliminate.`))return;try{const removedId=client.id;state.clients=state.clients.filter(c=>c.id!==removedId);state.deletedClientIds=[...new Set([...(state.deletedClientIds||[]),removedId])];delete state.tracked[removedId];delete state.compare[removedId];state.tasks=state.tasks.filter(t=>t.clientId!==removedId);for(const key of Object.keys(state.evaluations))if(key.startsWith(removedId+':'))delete state.evaluations[key];state.selectedClientId=state.clients[0]?.id||null;state.selectedCallId=null;state.editingClient=state.clients.length?null:'new';state.tab=state.clients.length?'dashboard':'profile';await persistNow();try{const docs=await idbListDocuments(removedId);for(const doc of docs)await idbDeleteDocument(doc.id)}catch(docErr){console.warn('Document cleanup skipped during client deletion',docErr)}await renderWorkspace()}catch(err){console.error('Consultant client delete failed',err);alert('Ștergerea nu a putut fi finalizată. Reîncarcă pagina și încearcă din nou.')}});
 root.querySelectorAll('[data-cw3-remove-demo]').forEach(b=>b.onclick=async()=>{if(!confirm('Elimini firmele și organizațiile exemplu?'))return;const ids=new Set(state.clients.filter(c=>c.seed).map(c=>c.id));state.clients=state.clients.filter(c=>!c.seed);for(const id of ids){delete state.tracked[id];delete state.compare[id]}state.tasks=state.tasks.filter(t=>!ids.has(t.clientId));state.demoClientsRemoved=true;state.deletedClientIds=[...new Set([...(state.deletedClientIds||[]),...ids])];state.selectedClientId=state.clients[0]?.id||null;state.editingClient=state.clients.length?null:'new';state.tab=state.clients.length?'dashboard':'profile';await persistNow();await renderWorkspace()});
 const q=document.getElementById('cw3FilterQ');if(q)q.oninput=()=>{state.filters.q=q.value;persist();clearTimeout(q._t);q._t=setTimeout(renderWorkspace,250)};
 const st=document.getElementById('cw3FilterStatus');if(st)st.onchange=()=>{state.filters.status=st.value;persist();renderWorkspace()};
 const sc=document.getElementById('cw3FilterScore');if(sc)sc.onchange=()=>{state.filters.minScore=Number(sc.value);persist();renderWorkspace()};
 const ot=document.getElementById('cw3OnlyTracked');if(ot)ot.onchange=()=>{state.filters.onlyTracked=ot.checked;persist();renderWorkspace()};
 const ds=document.getElementById('cw3DossierCall');if(ds)ds.onchange=()=>{state.selectedCallId=ds.value;persist();renderWorkspace()};
 root.querySelectorAll('[data-cw3-answer]').forEach(s=>s.onchange=()=>{const client=selectedClient(),call=D.calls.find(c=>c.id===state.selectedCallId);if(!client||!call)return;const key=evaluationKey(client,call),e=getEvaluation(client,call);e.answers[s.dataset.cw3Answer]=s.value;e.updatedAt=new Date().toISOString();state.evaluations[key]=e;persist();renderWorkspace()});
 const note=document.getElementById('cw3DecisionNote');if(note)note.onchange=()=>{const client=selectedClient(),call=D.calls.find(c=>c.id===state.selectedCallId);if(!client||!call)return;const key=evaluationKey(client,call),e=getEvaluation(client,call);e.decisionNote=note.value;e.updatedAt=new Date().toISOString();state.evaluations[key]=e;persist()};
 root.querySelectorAll('[data-cw3-generate-tasks]').forEach(b=>b.onclick=()=>{const call=D.calls.find(c=>c.id===b.dataset.cw3GenerateTasks);if(call)generateTasks(selectedClient(),call)});
 root.querySelectorAll('[data-cw3-docs-for-call]').forEach(b=>b.onclick=()=>{state.selectedCallId=b.dataset.cw3DocsForCall;state.tab='documents';persist();renderWorkspace()});
 const taskForm=document.getElementById('cw3TaskForm');if(taskForm)taskForm.onsubmit=e=>{e.preventDefault();addTask({clientId:selectedClient().id,callId:document.getElementById('cw3TaskCall').value||null,title:document.getElementById('cw3TaskTitle').value.trim(),due:document.getElementById('cw3TaskDue').value,priority:document.getElementById('cw3TaskPriority').value});persist();renderWorkspace()};
 root.querySelectorAll('[data-cw3-task-done]').forEach(x=>x.onchange=()=>{const t=state.tasks.find(t=>t.id===x.dataset.cw3TaskDone);if(t){t.done=x.checked;t.completedAt=x.checked?new Date().toISOString():null;persist();renderWorkspace()}});
 root.querySelectorAll('[data-cw3-task-delete]').forEach(b=>b.onclick=()=>{state.tasks=state.tasks.filter(t=>t.id!==b.dataset.cw3TaskDelete);persist();renderWorkspace()});
 const upload=document.getElementById('cw3UploadForm');if(upload)upload.onsubmit=async e=>{e.preventDefault();const files=[...document.getElementById('cw3Files').files];if(!files.length)return;const client=selectedClient(),category=document.getElementById('cw3DocCategory').value,callId=document.getElementById('cw3DocCall').value||null;for(const file of files){await idbPutDocument({id:uid('doc'),clientId:client.id,callId,category,name:file.name,type:file.type,size:file.size,addedAt:new Date().toISOString(),blob:file})}await refreshDocuments(client);renderWorkspace()};
 root.querySelectorAll('[data-cw3-doc-download]').forEach(b=>b.onclick=async()=>{const d=await idbGetDocument(b.dataset.cw3DocDownload);if(d?.blob)downloadBlob(d.blob,d.name)});
 root.querySelectorAll('[data-cw3-doc-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Ștergi documentul local?'))return;await idbDeleteDocument(b.dataset.cw3DocDelete);await refreshDocuments(selectedClient());renderWorkspace()});
 root.querySelectorAll('[data-cw3-export],[data-cw3-export-quick]').forEach(b=>b.onclick=()=>exportState(false));
 root.querySelectorAll('[data-cw3-export-client]').forEach(b=>b.onclick=()=>exportState(true));
 root.querySelectorAll('[data-cw3-import]').forEach(b=>b.onclick=async()=>{const file=document.getElementById('cw3ImportFile').files[0];if(!file)return;try{const payload=JSON.parse(await file.text());const incoming=payload.state||payload;if(!incoming.clients||!confirm('Importul va înlocui workspace-ul curent. Continui?'))return;state=mergeSeeds(incoming);await persistNow();renderWorkspace()}catch(e){alert(`Backup invalid: ${e.message}`)}});
 root.querySelectorAll('[data-cw3-reset]').forEach(b=>b.onclick=async()=>{if(!confirm('Ștergi definitiv workspace-ul și documentele locale?'))return;state=baseState();await idbClearDocuments().catch(()=>{});safeLocalSet(LOCAL_KEY,state);await persistNow();state.editingClient='new';renderWorkspace()});
 root.querySelectorAll('[data-cw3-exit]').forEach(b=>b.onclick=()=>document.getElementById('mode')?.click());
}

loadState().then(()=>{
 const activate=()=>{const main=document.querySelector('.main'),mode=document.getElementById('mode');if(main&&mode&&['Site public','Public site'].includes(mode.textContent.trim())&&main.dataset.cw3!=='1')setTimeout(renderWorkspace,0)};
 const obs=new MutationObserver(activate);obs.observe(document.getElementById('app'),{childList:true,subtree:true});
 document.addEventListener('click',e=>{if(e.target?.id==='mode')setTimeout(activate,0)},true);
 activate();
}).catch(err=>console.error('Consultant Workspace v3 init failed',err));
})();
